<?php
/** Declarative Office Seven configuration. Never executes HTML, scripts, CSS or SQL. */
function uiCatalog(): array {static $catalog=null;if($catalog===null)$catalog=json_decode(file_get_contents(__DIR__.'/ui-catalog.json'),true,512,JSON_THROW_ON_ERROR);return $catalog;}
function designInvalid(): never {jsonResponse(false,null,'Invalid Office Seven configuration.',400);}
function designObject($v,array $keys): void {if(!is_array($v)||(array_is_list($v)&&count($v)>0)||array_diff(array_keys($v),$keys))designInvalid();}
function designList($v,int $max): void {if(!is_array($v)||!array_is_list($v)||count($v)>$max)designInvalid();}
function designString($v,int $max=5000): void {if(!is_string($v)||strlen($v)>$max*4||str_contains($v,"\0"))designInvalid();}
function designColor($v): void {if(!is_string($v)||!preg_match('/^#[0-9a-f]{6}$/iD',$v))designInvalid();}
function designNumber($v,float $min,float $max): void {if(!is_int($v)&&!is_float($v)||!is_finite((float)$v)||$v<$min||$v>$max)designInvalid();}
function designEnum($v,array $list): void {if(!in_array($v,$list,true))designInvalid();}
function designBoolean($v): void {if(!is_bool($v))designInvalid();}
function designLocal($v): void {designObject($v,['en','fa','ps']);foreach($v as $text)designString($text);}
function designUniqueIds(array $items): void {$ids=[];foreach($items as $item){$id=$item['id']??null;if(!is_string($id)||!preg_match('/^[a-zA-Z0-9_-]{1,80}$/D',$id)||isset($ids[$id]))designInvalid();$ids[$id]=true;}}
function validateDesign($d): void {
 if($d===null)return;
 designObject($d,['themeChoices','defaultTheme','headerColor','accentColor','radius','density','cards','clocks','buttons','moduleSettings','palette','fontScale','fontFamily','sidebarWidth','contentWidth','gap','shadow','brand','footer','hero','header','navOrder','texts','accountTexts','moduleLayouts','pages']);if(strlen(json_encode($d))>350000)designInvalid();
 $themeIds=['skeuomorphism','bento','aurora','handdrawn','figma','glassmorphism','neumorphism','claymorphism'];
 if(isset($d['defaultTheme']))designEnum($d['defaultTheme'],$themeIds);
 if(isset($d['themeChoices'])){designList($d['themeChoices'],4);foreach($d['themeChoices'] as $theme)designEnum($theme,$themeIds);if(count($d['themeChoices'])!==4||count(array_unique($d['themeChoices']))!==4)designInvalid();}
 $catalog=uiCatalog();$mods=array_column($catalog['modules'],null,'id');$routes=array_merge(['dashboard','reports','accounting','notifications','settings','staff','audit_logs','services','guide','assistant','drive','backup','calculator','about'],array_keys($mods));
 designList($d['pages']??[],30);foreach($d['pages']??[] as $p){if(!is_array($p))designInvalid();$routes[]=$p['id']??'';}
 foreach(['headerColor','accentColor'] as $k)if(isset($d[$k]))designColor($d[$k]);
 foreach(['radius'=>[0,40],'fontScale'=>[85,125],'sidebarWidth'=>[200,320],'contentWidth'=>[900,2400],'gap'=>[8,40]] as $k=>$range)if(isset($d[$k]))designNumber($d[$k],...$range);
 foreach(['density'=>['compact','comfortable','large'],'fontFamily'=>['system','serif','mono'],'shadow'=>['none','soft','strong']] as $k=>$values)if(isset($d[$k]))designEnum($d[$k],$values);
 foreach(['brand','footer'] as $k)if(isset($d[$k]))designLocal($d[$k]);
 if(isset($d['palette'])){designObject($d['palette'],['bg','white','ink','muted','line','sidebar','sidebarText']);foreach($d['palette'] as $c)designColor($c);}
 if(isset($d['hero'])){designObject($d['hero'],['gradient','endColor','textColor','padding','radius','layout','visible']);foreach($d['hero'] as $k=>$v){if(in_array($k,['gradient','visible']))designBoolean($v);elseif(in_array($k,['endColor','textColor']))designColor($v);elseif($k==='padding')designNumber($v,16,64);elseif($k==='radius')designNumber($v,0,60);else designEnum($v,['row','column','reverse']);}}
 if(isset($d['header'])){designObject($d['header'],['color','textColor','order','hidden']);foreach($d['header'] as $k=>$v){if(in_array($k,['color','textColor']))designColor($v);else{designList($v,12);if(count($v)!==count(array_unique($v)))designInvalid();foreach($v as $x)designEnum($x,$k==='order'?['project','breadcrumb','search','install','add']:['breadcrumb','search','install','add','theme','notifications','user']);}}}
 if(isset($d['navOrder'])){designList($d['navOrder'],60);foreach($d['navOrder'] as $v)designEnum($v,$routes);if(count($d['navOrder'])!==count(array_unique($d['navOrder'])))designInvalid();}
 if(isset($d['texts'])){designObject($d['texts'],$catalog['labels']);foreach($d['texts'] as $v)designLocal($v);}
 if(isset($d['accountTexts'])){if(!is_array($d['accountTexts'])||count($d['accountTexts'])>200)designInvalid();foreach($d['accountTexts'] as $code=>$v){if(!preg_match('/^\d{4}$/D',(string)$code))designInvalid();designLocal($v);}}
 if(isset($d['moduleSettings'])){designObject($d['moduleSettings'],$routes);foreach($d['moduleSettings'] as $v){designObject($v,['visible','locked','disabledActions']);foreach(['visible','locked'] as $k)if(isset($v[$k]))designBoolean($v[$k]);if(isset($v['disabledActions'])){designList($v['disabledActions'],8);foreach($v['disabledActions'] as $x)designEnum($x,['view','create','edit','delete','approve','reverse','print','export']);}}}
 foreach(['cards'=>30,'clocks'=>24,'buttons'=>24,'pages'=>30] as $key=>$max)if(isset($d[$key])){designList($d[$key],$max);designUniqueIds($d[$key]);foreach($d[$key] as $item){
  if($key==='cards'){designObject($item,['id','kind','visible','width','title','body','color','minHeight']);designEnum($item['kind']??'', ['kpis','costs','budget','recent','units','smart','note']);designEnum($item['width']??0,[3,4,5,6,7,8,12]);if(isset($item['visible']))designBoolean($item['visible']);foreach(['title','body'] as $k)if(isset($item[$k]))designLocal($item[$k]);if(isset($item['color']))designColor($item['color']);if(isset($item['minHeight']))designNumber($item['minHeight'],0,800);}
  elseif($key==='clocks'){designObject($item,['id','kind','timezone','size','placement']);designEnum($item['kind']??-1,[0,1,2,3,4,5]);designString($item['timezone']??'',100);try{new DateTimeZone($item['timezone']);}catch(Throwable $e){designInvalid();}if(isset($item['size']))designNumber($item['size'],60,180);if(isset($item['placement']))designEnum($item['placement'],['hero','header','dashboard']);}
  elseif($key==='buttons'){designObject($item,['id','label','action','visible','color','mode','url','placement','size','variant','radius']);designEnum($item['action']??'',$routes);designLocal($item['label']??[]);designColor($item['color']??'');if(isset($item['visible']))designBoolean($item['visible']);if(isset($item['mode']))designEnum($item['mode'],['create','navigate','print','export','install','theme','link']);if(($item['mode']??'create')==='create'&&!isset($mods[$item['action']]))designInvalid();if(($item['mode']??'')==='export'&&!isset($mods[$item['action']])&&!in_array($item['action'],['reports','accounting']))designInvalid();if(isset($item['url'])){designString($item['url'],2000);if($item['url']!==''&&(!filter_var($item['url'],FILTER_VALIDATE_URL)||!in_array(strtolower(parse_url($item['url'],PHP_URL_SCHEME)??''),['https','http'])||parse_url($item['url'],PHP_URL_USER)!==null))designInvalid();}if(($item['mode']??'')==='link'&&empty($item['url']))designInvalid();if(isset($item['placement']))designEnum($item['placement'],['hero','header']);if(isset($item['size']))designEnum($item['size'],['small','normal','large']);if(isset($item['variant']))designEnum($item['variant'],['solid','outline']);if(isset($item['radius']))designNumber($item['radius'],0,40);}
  else {designObject($item,['id','title','body','visible','links']);if(!preg_match('/^custom_[a-zA-Z0-9-]{1,60}$/D',$item['id']))designInvalid();designLocal($item['title']??[]);designLocal($item['body']??[]);if(isset($item['visible']))designBoolean($item['visible']);designList($item['links']??[],30);foreach($item['links']??[] as $x)designEnum($x,$routes);}
 }}
 if(isset($d['moduleLayouts'])){designObject($d['moduleLayouts'],array_keys($mods));foreach($d['moduleLayouts'] as $id=>$layout){designObject($layout,['fields','fieldOrder','columns','extraFields']);$fields=array_column($mods[$id]['fields'],null,'key');$extra=[];designList($layout['extraFields']??[],20);foreach($layout['extraFields']??[] as $f){designObject($f,['key','label','type','required']);if(!is_string($f['key']??null)||!preg_match('/^x_[a-zA-Z0-9-]{1,60}$/D',$f['key'])||isset($extra[$f['key']]))designInvalid();designLocal($f['label']??[]);designEnum($f['type']??'',['text','number','date','textarea']);designBoolean($f['required']??false);$extra[$f['key']]=$f;}$keys=array_merge(array_keys($fields),array_keys($extra));if(isset($layout['fields'])){designObject($layout['fields'],$keys);foreach($layout['fields'] as $key=>$v){designObject($v,['visible','width','label']);if(isset($v['visible'])){designBoolean($v['visible']);if(($fields[$key]['required']??false)&&!$v['visible'])designInvalid();}if(isset($v['width']))designEnum($v['width'],[1,2]);if(isset($v['label']))designLocal($v['label']);}}foreach(['fieldOrder'=>$keys,'columns'=>array_merge($mods[$id]['columns'],array_keys($extra))] as $key=>$permitted)if(isset($layout[$key])){designList($layout[$key],100);foreach($layout[$key] as $x)designEnum($x,$permitted);if(count($layout[$key])!==count(array_unique($layout[$key])))designInvalid();}}}
}
function validateOfficeSettings(array $document): void {
 $settings=$document['appSettings']??[];validateDesign($settings['dashboardDesign']??null);if(isset($settings['designHistory'])){designList($settings['designHistory'],20);foreach($settings['designHistory'] as $d)validateDesign($d);}
}
function validateExtraFields(array $previous,array $document): void {
 $layouts=$document['appSettings']['dashboardDesign']['moduleLayouts']??[];$catalog=uiCatalog();
 foreach($catalog['modules'] as $module){$collection=$module['collection'];$defs=array_column($layouts[$module['id']]['extraFields']??[],null,'key');$before=array_column($previous[$collection]??[],null,'id');foreach($document[$collection]??[] as $row){$old=$before[$row['id']]??null;if($old==$row)continue;foreach($row as $key=>$value)if(str_starts_with($key,'x_')){if($old&&($row['approvalStatus']??'draft')!=='draft'&&array_key_exists($key,$old)&&$old[$key]===$value)continue;if(!isset($defs[$key])){if($old&&($old[$key]??null)===$value)continue;designInvalid();}$f=$defs[$key];if($f['type']==='number'){designNumber($value,0,1e12);}else{designString($value);if($f['type']==='date'&&$value!==''){$date=DateTimeImmutable::createFromFormat('!Y-m-d',$value);if(!$date||$date->format('Y-m-d')!==$value)designInvalid();}}}
 // Existing financial documents retain their signed contents when configuration changes.
 if(in_array($row['approvalStatus']??'draft',['draft','submitted','approved'],true)&&!isset($row['reversal']))foreach($defs as $key=>$f)if($f['required']&&(!array_key_exists($key,$row)||trim((string)$row[$key])===''))designInvalid();
 }}
}
function enforceConfiguredActions(array $user,array $previous,array $document): void {
 if($user['is_master'])return;$locks=$previous['appSettings']['dashboardDesign']['moduleSettings']??[];
 foreach(uiCatalog()['modules'] as $m){$disabled=$locks[$m['id']]['disabledActions']??[];if(!$disabled)continue;$old=array_column($previous[$m['collection']]??[],null,'id');$new=array_column($document[$m['collection']]??[],null,'id');foreach(array_unique(array_merge(array_keys($old),array_keys($new))) as $id){$a=$old[$id]??null;$b=$new[$id]??null;if($a==$b)continue;$action=$a===null?'create':($b===null?'delete':'edit');if($a&&$b&&($a['approvalStatus']??null)!==($b['approvalStatus']??null))$action=in_array($b['approvalStatus']??'', ['approved','posted'],true)?'approve':'edit';if($a&&$b&&(($a['reversal']??null)!=($b['reversal']??null)||($a['partialReversals']??[])!=($b['partialReversals']??[])))$action='reverse';if(in_array($action,$disabled,true)||in_array('view',$disabled,true))jsonResponse(false,null,'This operation is disabled by Office Seven.',403);}}
}
